/// <summary>
/// SysOperation controller that runs <c>CELTIntegrationService.run</c>, either interactively or as
/// a recurring batch. Mirrors the original ELTIntegrationController.
/// </summary>
internal class CELTIntegrationController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
/// Menu-item entry point.
/// </summary>
/// <param name = "_args">menu args</param>
public static void main(Args _args)
{
    CELTIntegrationController controller = new CELTIntegrationController();

    controller.parmExecutionMode(SysOperationExecutionMode::Synchronous);
    controller.parmDialogCaption("@CELTLabels:ClearELTIntegration");
    controller.startOperation();
}
